window.addEventListener("load", async function (event) {
	await parsingPartNumID();
	// 由於Electron無法get navigator.usb，所以Electron就在main讀，web就在worker讀
	if (isElectron()) {
		setIPCListener();
	}
	else if (isExtension()) {
		window.vscode = window.vscode || acquireVsCodeApi();
		window.alert = function (msg) {
			window.vscode.postMessage({ 'action': 'showWarningMessage', 'data': msg });
		};
		setExtensionListener();
	} else {
		if (window.Worker) {
			worker = new Worker('./worker/webusb.worker-bundle.js');
			setWorkerListener();
		}
	}
});

// [Workaround] Generate Code wizard support profile/cppcmd/astyle/rename options.
setGlobalVariables("NUTOOL_PER", "g_bDevelopingTool");

const restoreGPIO = function () {
	// restore the saved GPIO pins
	for (let i = 0, max = g_pinsConfiguredByGPIO.length; i < max; i += 1) {
		let pinDescription = g_chipPinDescriptions[g_pinsConfiguredByGPIO[i]];
		pinDescription = pinDescription.slice(pinDescription.indexOf('P'));
		while (pinDescription.indexOf('.') !== -1 && pinDescription.indexOf('.') !== 2) {
			pinDescription = pinDescription.slice(1);
			pinDescription = pinDescription.slice(pinDescription.indexOf('P'));
		}

		pinDescription = pinDescription.slicePriorToX('/');

		// we must replace them with other suitable one
		const currentNode = pinDescription + '_Pin' + (g_pinsConfiguredByGPIO[i] + 1);
		if (typeof globalThis.triggerModuleTreeCheck === 'function') {
			setTimeout(async function () {
				await globalThis.triggerModuleTreeCheck(currentNode, true);
			}, 0);
		}
	}
}

const Toolbar = (props) => {
	const { i18n, t } = useTranslation();
	const r_chipType = useSelector((state) => state.r_chipType);
	const r_partNumber_package = useSelector((state) => state.r_partNumber_package);
	// const r_cfg_perFunctions = useSelector((state) => state.r_cfg_perFunctions);
	const r_currentTool = useSelector((state) => state.r_currentTool);
	const r_settings_hideAllPin = useSelector((state) => state.r_settings_hideAllPin);
	const r_pinCurrentDescription = useSelector((state) => state.r_pinCurrentDescription);
	const dispatch = useDispatch();
	EXPORT_REACT.dispatch = dispatch;

	const [open, setOpen] = useState(false);
	const [autoAssignOpen, setAutoAssignOpen] = useState(false);

	const showDrawer = (bShow) => {
		setOpen(bShow===true);
	};

	// // From fterMCUchange()
	// const handleChangePartNo = (value, node) => {
	// 	dispatch(set_partNumber_package(value));
	// 	dispatch(set_partNumber_type(node.type));
	// 	dispatch(set_cfg_perFunctions([]));
	// 	dispatch(setSnippetName(""));
	// };

	const bHidden = function(array=[]){
		return array.includes(r_currentTool);
	}

	const generateCodeFromToolbar = (projectName, bModularizeCode) => {
		const versionCode = `v${version}`;
		const briefName = g_briefName;
		const companyName = g_copyrightCompanyName;
		const partNumber = r_partNumber_package;
		const year = (new Date()).getFullYear();
		const now = new Date();

		getGeneratedCodeByPin();
		getGeneratedCodeByModule();
		getGeneratedCodeByGPIO();

		getIncludeHeadFile();
		const includeHeadFileString = g_includeHeadFileString || "";
		const generatedCodeByPinString = g_generatedCodeByPinString || "";
		const generatedCodeByModuleString = g_generatedCodeByModuleString || "";
		const generatedCodeByGPIOstring = g_generatedCodeByGPIOstring || "";

		// Generate .c + .h / .c
		if (bModularizeCode) {
			getModularizedDataUsedToCreateText();
			const userDefinedPinString = g_userDefinedPinString || "";
			const gpioMFPsString = g_gpio_MFPsString || "";
			const gpioMFPsString1 = g_gpio_MFPsString1 || "";

			const textc = `/****************************************************************************\r\n`
				+ ` * @file     ${projectName}.c\r\n`
				+ ` * @version  ${versionCode}\r\n`
				+ ` * @Date     ${now}\r\n`
				+ ` * @brief    ${briefName} generated code file\r\n`
				+ ` *\r\n`
				+ ` * SPDX-License-Identifier: Apache-2.0\r\n`
				+ ` *\r\n`
				+ ` * Copyright (C) 2013-${year}${companyName} All rights reserved.\r\n`
				+ `*****************************************************************************/\r\n`
				+ `\r\n`
				+ `/********************\r\n`
				+ `MCU:${partNumber}\r\n`
				+ (generatedCodeByPinString === "" ? "" : `Pin Configuration:\r\n${generatedCodeByPinString}`)
				+ (generatedCodeByModuleString === "" ? "" : `Module Configuration:\r\n${generatedCodeByModuleString}`)
				+ (generatedCodeByGPIOstring === "" ? "" : `GPIO Configuration:\r\n${generatedCodeByGPIOstring}`)
				+ `********************/\r\n\r\n`
				+ `${includeHeadFileString}`
				+ (userDefinedPinString === "" ? "" : `\r\n${userDefinedPinString}`)
				+ `${gpioMFPsString}`
				+ `\r\n\r\n/*** (C) COPYRIGHT 2013-${year}${companyName} ***/\r\n`;

			const texth = `/****************************************************************************\r\n`
				+ ` * @file     ${projectName}.h\r\n`
				+ ` * @version  ${versionCode}\r\n`
				+ ` * @Date     ${now}\r\n`
				+ ` * @brief    ${briefName} generated code file\r\n`
				+ ` *\r\n`
				+ ` * SPDX-License-Identifier: Apache-2.0\r\n`
				+ ` *\r\n`
				+ ` * Copyright (C) 2013-${year}${companyName} All rights reserved.\r\n`
				+ `*****************************************************************************/\r\n\r\n`
				+ `#ifndef __${projectName.toUpperCase()}_H__\r\n`
				+ `#define __${projectName.toUpperCase()}_H__\r\n\r\n`
				+ `#ifdef __cplusplus\r\nextern \"C\"\r\n{\r\n#endif\r\n`
				+ `${gpioMFPsString1}`
				+ `#ifdef __cplusplus\r\n}\r\n#endif\r\n`
				+ `#endif /*__${projectName.toUpperCase()}_H__*/\r\n\r\n`
				+ `/*** (C) COPYRIGHT 2013-${year}${companyName} ***/\r\n`;

			saveAs(new Blob([textc], { type: "text/plain;charset=utf-8" }), `${projectName}.c`);
			saveAs(new Blob([texth], { type: "text/plain;charset=utf-8" }), `${projectName}.h`);
		}
		else {
			getDataUsedToCreateText();
			const userDefinedPinString = g_userDefinedPinString || "";
			const gpioMFPsString = g_gpio_MFPsString || "";
			const textc = `/****************************************************************************\r\n`
				+ ` * @file     ${projectName}.c\r\n`
				+ ` * @version  ${versionCode}\r\n`
				+ ` * @Date     ${now}\r\n`
				+ ` * @brief    ${briefName} generated code file\r\n`
				+ ` *\r\n`
				+ ` * SPDX-License-Identifier: Apache-2.0\r\n`
				+ ` *\r\n`
				+ ` * Copyright (C) 2013-${year}${companyName} All rights reserved.\r\n`
				+ `*****************************************************************************/\r\n`
				+ `\r\n`
				+ `/********************\r\n`
				+ `MCU:${partNumber}\r\n`
				+ (generatedCodeByPinString === "" ? "" : `Pin Configuration:\r\n${generatedCodeByPinString}`)
				+ (generatedCodeByModuleString === "" ? "" : `Module Configuration:\r\n${generatedCodeByModuleString}`)
				+ (generatedCodeByGPIOstring === "" ? "" : `GPIO Configuration:\r\n${generatedCodeByGPIOstring}`)
				+ `********************/\r\n\r\n`
				+ `${includeHeadFileString}`
				+ (userDefinedPinString === "" ? "" : `\r\n${userDefinedPinString}`)
				+ `/*\r\n`
				+ ` * @brief This function provides the configured MFP registers\r\n`
				+ ` * @param None\r\n`
				+ ` * @return None\r\n`
				+ ` */\r\n`
				+ `void SYS_Init(void)\r\n{\r\n`
				+ `${gpioMFPsString}`
				+ `\r\n    return;\r\n}\r\n\r\n`
				+ `/*** (C) COPYRIGHT 2013-${year}${companyName} ***/\r\n`;

			saveAs(new Blob([textc], { type: "text/plain;charset=utf-8" }), `${projectName}.c`);
		}

		// Generate .ncfg
		get_gpio_MFPsNames();
		const pinCurrentStateString = g_pinCurrentStateString || "";
		const pinsConfiguredByGPIOstring = g_pinsConfiguredByGPIOstring || "";
		const userDefinedPinString = g_userDefinedPinString || "";
		const gpioMFPsString = g_gpio_MFPsString || "";
		const textcfg = `/****************************************************************************\r\n`
			+ ` * @file     ${projectName}.ncfg\r\n`
			+ ` * @version  ${versionCode}\r\n`
			+ ` * @Date     ${now}\r\n`
			+ ` * @brief    ${briefName} config file\r\n`
			+ ` *\r\n`
			+ ` * @note Please do not modify this file.\r\n`
			+ ` *       Otherwise, it may not be loaded successfully.\r\n`
			+ ` *\r\n`
			+ ` * SPDX-License-Identifier: Apache-2.0\r\n`
			+ ` *\r\n`
			+ ` * Copyright (C) 2013-${year}${companyName} All rights reserved.\r\n`
			+ `*****************************************************************************/\r\n`
			+ `MCU:${partNumber}\r\n`
			+ `${pinCurrentStateString}`
			+ `${pinsConfiguredByGPIOstring}`
			+ `${userDefinedPinString}`
			+ `${gpioMFPsString}`
			+ `/*** (C) COPYRIGHT 2013-${year}${companyName} ***/\r\n`;

		saveAs(new Blob([textcfg], { type: "text/plain;charset=utf-8" }), `${projectName}.ncfg`);
	};

	const onOkFunc = async () => {
		NUTOOL_PIN.projectName = localStorage.getItem("ProjectName") || NUTOOL_PIN.projectName || "MyProject";
		NUTOOL_PIN.modularizeCode = localStorage.getItem("CheckModularizeCode") === "Yes";

		Modal.confirm({
			title: t("BTN_GENERATE_CODE"),
			width: 570,
			content: 
				<div>
					<p>{t("TEXT_GENERATE_CODE")}</p>
					<Form style={{ marginBottom: 8 }}>
						<Form.Item label={t("LBL_PROJECT_NAME")}>
							<Input
								defaultValue={NUTOOL_PIN.projectName}
								placeholder={t("LBL_PROJECT_NAME")}
								onChange={(e) => {
									NUTOOL_PIN.projectName = e.target.value;
								}}
							/>
						</Form.Item>
					</Form>
					<Checkbox
						defaultChecked={NUTOOL_PIN.modularizeCode}
						style={{ fontWeight: "normal" }}
						onChange={(e) => {
							NUTOOL_PIN.modularizeCode = e.target.checked;
						}}>
						{t("TEXT_MODULARIZE_CODE")}
					</Checkbox>
				</div>,
			onOk: () => {
				const projectName = (NUTOOL_PIN.projectName || "MyProject").trim() || "MyProject";
				const bModularizeCode = !!NUTOOL_PIN.modularizeCode;

				localStorage.setItem("ProjectName", projectName);
				localStorage.setItem("CheckModularizeCode", bModularizeCode ? "Yes" : "No");

				try {
					generateCodeFromToolbar(projectName, bModularizeCode);
				}
				catch (err) {
					console.error(err);
					Modal.error({
						title: t("BTN_GENERATE_CODE"),
						content: err?.message || String(err)
					});
				}
			}
		});
	};

	// Apply a .ncfg configuration text (from a file or from the auto-saved localStorage entry).
	// The work is finished asynchronously, so failures are reported through onError() instead of throwing.
	const loadConfigFromText = (result, onError) => {
		const handleFailure = (err) => {
			if (typeof onError === 'function') {
				onError(err);
			}
			else {
				console.error(err);
			}
		};

		var newPartNumberPackage = result.sliceAfterX('MCU:').slicePriorToX('\r');
		if (!newPartNumberPackage || !newPartNumberPackage.includes('(') || !newPartNumberPackage.includes(')')) {
			handleFailure(new Error("Invalid MCU part number in the configuration: " + newPartNumberPackage));
			return;
		}
		var newChipType = decideNewChipType(newPartNumberPackage);
		var oldfilename = 'NUC_' + chipSeriesToChipType(r_chipType) + '_Content.js';
		var newfilename = 'NUC_' + newChipType + '_Content.js';

		NUTOOL_PIN.g_readConfigFileContentText = result;

		replacejscssfile(oldfilename, newfilename, 'js', function(){
			try {
				// decideNewChipType() silently falls back to the default chip type for an unknown part
				// number, which would draw the default chip with the saved pin names on top of it.
				var newPartNumber = newPartNumberPackage.slicePriorToX('(');
				if (!Array.isArray(NUTOOL_PIN.g_cfg_chips) ||
					!NUTOOL_PIN.g_cfg_chips.some((chip) => chip.name === newPartNumber)) {
					throw new Error("Unknown part number in the configuration: " + newPartNumberPackage);
				}

				// NUTOOL_PER.readTreeContent(result);
				initializeAll();
				g_partNumber_package = newPartNumberPackage;
				NUTOOL_PIN.decidepackageNumber();
				if (typeof NUTOOL_PIN.g_cfg_pkgs[NUTOOL_PIN.g_packageNumberIndex] === 'undefined') {
					throw new Error("Unknown package in the configuration: " + newPartNumberPackage);
				}
				decideNUC_Pin_Total_Side_Number();
				dispatch(setChipType(chipTypeToChipSeries(newChipType)));
				dispatch(set_partNumber_package(newPartNumberPackage));

				refresh();
				// dispatch(setMfpRegisterName(Object.assign([], g_gpio_MFPs)));
				dispatch(set_module_functions(Object.assign([], g_module_functions)));

				readGPIOMFPsAndGPIOpins(result);
				g_gpio_MFPs = g_read_gpio_MFPs;
				dispatch(setMfpRegisterName(Object.assign([], g_gpio_MFPs)));
				dispatch(setPinCurrentDescription(
					Object.assign([],
						NUTOOL_PIN.g_cfg_pkgs[NUTOOL_PIN.g_packageNumberIndex].map(
							(value, index) => {
								// Some packages declare the default pin name with padding spaces
								// (EX: I94 'PA.0   '), while the saved description is trimmed.
								// Compare them without the padding so that an untouched pin is not
								// mistaken for a user-configured one.
								const savedDescription = (g_read_cfg_pkgs[index] || "").trim();
								return savedDescription === String(value).trim() ? "" : savedDescription;
							}
						)
					)
				));
				restoreGPIO();
			}
			catch (err) {
				handleFailure(err);
			}
		}, true, handleFailure);
	};

	// Expose the loader so that the initial render can restore the auto-saved configuration
	// before the default chip series content is loaded.
	EXPORT_REACT.loadConfigFromText = loadConfigFromText;

	// Keep the latest pin descriptions reachable from the "beforeunload" handler below.
	const pinCurrentDescriptionRef = useRef(r_pinCurrentDescription);
	pinCurrentDescriptionRef.current = r_pinCurrentDescription;

	// Auto-save the current configuration so it can be restored on the next start-up.
	useEffect(() => {
		const onBeforeUnload = function () {
			try {
				g_pinCurrentDescription = pinCurrentDescriptionRef.current;
				updateg_pinCurrentModule(pinCurrentDescriptionRef.current);
				updateg_pinsConfiguredByGPIO(pinCurrentDescriptionRef.current);
				localStorage.setItem(NCFG_STORAGE_KEY, genConfig());
			}
			catch (err) {
				console.log("auto-save of the configuration failed, msg:" + err);
			}
		};

		window.addEventListener("beforeunload", onBeforeUnload);
		return () => window.removeEventListener("beforeunload", onBeforeUnload);
	}, []);

	$('#loadConfiguration').off('change').on('change', function(){
		if (this.files[0] === undefined || this.files[0] == null) return;
			var extension = this.files[0].name.split('.').pop().toLowerCase();  // file extension from input file
			if (extension.indexOf('cfg') === -1) {
				alert("Please select a file with a valid file type. (.ncfg)")
				return;
			}
			var uploadedFile = this.files[0];
			var fileReader = new FileReader();
			fileReader.readAsText(uploadedFile)
			fileReader.onload = function (reader) {
				try {
					var result = reader.target.result.replace(/\n/g, "\r\n"); // Unix(LF) -> Windows(CRLF);
					NUTOOL_PIN.g_readConfigFilePath = URL.createObjectURL(uploadedFile);
					loadConfigFromText(result);
				}
				catch (err) {
					console.error(err);
				}
			}
	});

	$('#bspForGenCode').off('change').on('change', function(){
		// TODO - Lack confirm function
		var file = this.files[0];
		if(file && file.webkitRelativePath.startsWith(RESTRICTION_FOLDER_NAME)){
			var path = file.path.slicePriorToX(RESTRICTION_FOLDER_NAME) + RESTRICTION_FOLDER_NAME;
			$("#generateCodeDialogInput").val(path);
		} 
	});
	
	return (
		<div style={{ display: "flex",justifyContent: "space-between" }}>
			<div style={{ display: "flex", alignItems: "center"}}>
			<MenuBtn
				id="ID_BUTTON_LOAD"
				src={load}
				alt={t("BTN_LOAD_CONFIGURATION")}
				onClick={() => {
					$('#loadConfiguration').trigger('click');
				}}
			/>
			<MenuBtn
				id="ID_BUTTON_SAVE"
				src={save}
				alt={t("BTN_SAVE_CONFIGURATION")}
				onClick={async() => {
						try {
							g_pinCurrentDescription = r_pinCurrentDescription;
							updateg_pinCurrentModule(r_pinCurrentDescription);
							updateg_pinsConfiguredByGPIO(r_pinCurrentDescription);
							var text = genConfig();
							var blob = new Blob([text], { type: "text/plain;charset=utf-8" });
							saveAs(blob, `${r_partNumber_package}.ncfg`);
						} catch (err) {
							console.log("saveConfig failed, meg:" + err);
						}
					//}
				}}
			/>
			<MenuBtn
				src={gen_code}
				alt={t("BTN_GENERATE_CODE")}
				onClick={() => {
					onOkFunc();
				}}
			/>
			<MenuBtn
				src={restore}
				hidden={true}
				alt={t("BTN_RETURN_TO_DEFAULT")}
				onClick={() => {
					switch(r_currentTool) {
						case CURRENT_TOOL.PERIPHERAL:
							// NUTOOL_PER.restoreToDefault();
							var oldfilename = 'NUC_' + chipSeriesToChipType(r_chipType) + '_Content.js';
							var newfilename = 'NUC_' + chipSeriesToChipType(CHIP_TYPE) + '_Content.js';
							replacejscssfile(oldfilename, newfilename, 'js', function(){
								initializeAll();
								dispatch(setChipType(CHIP_TYPE));
								dispatch(set_partNumber_package(PART_NUMBER[CHIP_TYPE].package));
								dispatch(set_partNumber_type(PART_NUMBER[CHIP_TYPE].type));
								dispatch(set_cfg_perFunctions([]));
								dispatch(setSnippetName(''));
							});
							break;
						case CURRENT_TOOL.CLOCK:
							NUTOOL_CLOCK.pageRefresh();
							break;
						default:
							break;
					}
				}}
			/>
			<MenuBtn
				id="ID_BUTTON_CONNECT_TO_TARGET"
				src={connect_chip_2}
				alt={t("BTN_CONNECT_TO_TARGET_CHIP")}
				onClick={async () => {
					EXPORT_REACT.BTN_CONNECT_TO_TARGET_CHIP = t("BTN_CONNECT_TO_TARGET_CHIP");
					EXPORT_REACT.TEXT_CONNECT_TO_TARGET_CHIP_ERR = t("TEXT_CONNECT_TO_TARGET_CHIP_ERR");
					if (isElectron()) {
						window.electronAPI.send('connect');
					}
					else if (isExtension()) {
						window.vscode.postMessage({ action: 'connect' });
					}
					else {
						let selectedDevice;
						selectedDevice = await navigator.usb.requestDevice({
							filters: [{ vendorId: 0x0416 }]
						}).catch(error => {
							console.log(error);
							selectedDevice = undefined;
						});
						if (selectedDevice) {
							connectToChipWeb(false, selectedDevice);
						}
					}
				}}
			/>
			<MenuBtn
				id="ID_BUTTON_PRINT_REPORT"
				src={print_report}
				alt={t("BTN_PRINT_REPORT")}
				onClick={() => showPrintReportDialog({ t })}
			/>
			<MenuBtn
				src={run_nucad}
				alt={t("BTN_RUN_NUCAD")}
				hidden={!isElectron()}
				onClick={() => showRunNuCADDialog({ t, partNumber: r_partNumber_package })}
			/>
			<MenuBtn
				id="ID_BUTTON_GENERATE_PIN_DESCRIPTIONS"
				src={gen_pin_description_report}
				alt={t("BTN_GENERATE_REPORT")}
				onClick={() => {
					generatePinDescriptions();
				}}
			/>
			<MenuBtn
				id="ID_BUTTON_SHOW_PIN_DESCRIPTIONS"
				src={switch_pin_description}
				alt={t("BTN_SWITCH_PIN_DESCRIPTION")}
				onClick={() => {
					dispatch(setSettings_hideAllPin(!r_settings_hideAllPin));
				}}
			/>
			<MenuBtn
				src={disable}
				alt={t("BTN_DISABLE_ALL_CHECKED_MODULES")}
				// hidden={bHidden([CURRENT_TOOL.PERIPHERAL])}
				onClick={() => {
					NUTOOL_PIN.g_cfg_pkgs[NUTOOL_PIN.g_packageNumberIndex].forEach((pinName, index) => {
						update_gpio_MFPs(index, pinName);
					});
					dispatch(setMfpRegisterName(Object.assign([], g_gpio_MFPs)));
					dispatch(setPinCurrentDescription(r_pinCurrentDescription.map(() => "")))
				}}
			/>
			<MenuBtn
				src={auto_assign}
				alt={t("BTN_AUTO_ASSIGN")}
				onClick={() => {
					setAutoAssignOpen(true);
				}}
			/>
			<PinAutoAssignmentModal
				open={autoAssignOpen}
				onClose={() => setAutoAssignOpen(false)}
			/>
			<MenuBtn
				src={settings}
				alt={t("BTN_LANGUAGE")}
				onClick={() => {
					//NUTOOL_PER.settings();
					showDrawer(true);
				}}
			/>
			<Drawer
				title={t("BTN_LANGUAGE")}
				size="default"
				onClose={() => showDrawer(false)}
				open={open}
			>
				<Radio.Group
					value={i18n.language}
					onChange={(e) => {
						i18n.changeLanguage(e.target.value);
						localStorage.setItem("UIlanguage", LANG_KEY_TO_VALUE[e.target.value]);
						switch(r_currentTool) {
							case CURRENT_TOOL.PIN:
								NUTOOL_PIN.changeUIlanguage();
								break;
							case CURRENT_TOOL.CLOCK:
								NUTOOL_CLOCK.changeUIlanguage();
								break;
							default:
								break;
						}
						let modulesWiz = document.getElementsByClassName("jq-toast-single jq-has-icon jq-icon-warning");
						if(modulesWiz.length > 0){
							NUTOOL_PER.showModulesNeedChecking();
						}
					}}
				>
					<Space direction="vertical">	
						<Radio value={"en"}>English</Radio>
						<Radio value={"zh-TW"}>繁體中文</Radio>
						<Radio value={"zh-CN"}>简体中文</Radio>
					</Space>
				</Radio.Group>
			</Drawer>
			<MenuBtn
				src={user_manual}
				alt={t("BTN_READ_USER_MANUAL")}
				onClick={ () => {
					try{
						if(isElectron()){
							window.electronAPI.send('openUserManual');
						}
						else if(isExtension()){
							window.vscode.postMessage({ action: 'openUserManual' });
						}
						else {
							window.open('https://www.nuvoton.com/resource-download.jsp?tp_GUID=UG1320220401093634');
						}
					}
					catch(e){
						console.error(e);
						window.open('https://www.nuvoton.com/resource-download.jsp?tp_GUID=UG1320220401093634');					}
				}}
			/>
			<MenuBtn
				id="ID_BUTTON_TEST"
				alt="TEST"
				hidden={true} // TODO
				onClick={ () => {
					// eslint-disable-next-line no-restricted-globals
					external.generateTestResult();
				}}
			/>
			</div>
			<div style={{ display: "flex", flexDirection: "column", alignItems: "flex-end", justifyContent: "center", paddingRight: "10px", lineHeight: 1, gap: "2px" }}>
				<img src={nuvoton} alt="Nuvoton" style={{ height: "18px" }} />
				<span style={{ fontSize: "20px", textAlign: "right", fontWeight: "bold" }}>
					v{version}{g_bDevelopingTool ? "-alpha" : ""}
				</span>
			</div>
		</div>
	);
};

export default Toolbar;