import { Tooltip } from 'antd';

import {
    convertColorHex,
    sharedTooltipProps,
    genRightPinCmpV2,
    genLeftPinCmpV2,
} from '../libs/drawSvg';

const leftPinNo = [1, 2, 3, 4, 5];
const rightPinNo = [6, 7, 8, 9, 10];

const offset = -480 + 5 * 25 + 5;

export function renderSVG(data, isHideAllFunc) {
    let { name, name_color, processor } = data;

    return (<svg width={1200+offset} height={1200+offset} xmlns="http://www.w3.org/2000/svg" overflow="visible">
        {/* <!-- Central square --> */}
        <g transform="translate(250, 250)" stroke="#000" strokeWidth="1">
            <rect rx="10" height={535+offset} width={205} fill="#000"/>
            <Tooltip key="center_group" {...sharedTooltipProps(processor.information)}>
                <text transform="rotate(90 175 175)" textAnchor="middle" fontSize="26" stroke="#fff" y={250} x={265+offset/2} fill={convertColorHex(name_color)}>
                    <tspan x={265+offset/2} dy={`${-(String(name).split("(").length) * 0.6 + 0.2}em`} stroke="#ff0000" fill="#ff0000" fontWeight="bold">Nuvoton</tspan>
                    {String(name).split("(").map((line, i, arr) => (
                        <tspan key={i} x={265+offset/2} dy={i === 0 ? '1.2em' : '1.2em'}>{line.replace(")", "")}</tspan>
                    ))}
                </text>
            </Tooltip>
            <circle cx="15" cy={15} r="5" stroke="#fff" fill="none" />
        </g>

        {/* <!-- Right component --> */}
        {genRightPinCmpV2(430, 730 + offset, rightPinNo, data, isHideAllFunc)}

        {/* <!-- Left component --> */}
        {genLeftPinCmpV2(195, 280, leftPinNo, data, isHideAllFunc)}
    </svg>);
};