import { Tooltip } from 'antd';

import {
    convertColorHex,
    sharedTooltipProps,
    genRightPinCmpV2,
    genLeftPinCmpV2,
    genTopPinCmpV2,
    genBottomPinCmpV2,
} from '../libs/drawSvg';

const bottomPinNo = [1, 2, 3, 4, 5, 6, 7, 8];
const topPinNo = [17, 18, 19, 20, 21, 22, 23, 24];
const rightPinNo = [9, 10, 11, 12, 13, 14, 15, 16];
const leftPinNo = [25, 26, 27, 28, 29, 30, 31, 32];

const offset = -480 + 8 * 25 + 5;

export function renderSVG(data, isHideAllFunc) {
    let { name, name_color, processor } = data;
    const labelX = 265 + offset / 2;
    const nameLines = String(name).split("(").map((line) => line.replace(")", ""));
    const chipNameColor = convertColorHex(name_color);

    return (<svg width={1200+offset} height={1200+offset} xmlns="http://www.w3.org/2000/svg" overflow="visible">
        {/* <!-- Central square --> */}
        <g transform="translate(250, 250)" stroke="#000" strokeWidth="1">
            <rect rx="10" height={535+offset} width={535+offset} fill="#000"/>
            <Tooltip key="center_group" {...sharedTooltipProps(processor.information)}>
                <text textAnchor="middle" fontSize="22" y={265+offset/2} x={labelX}>
                    <tspan x={labelX} dy={`${-(nameLines.length) * 0.6}em`} stroke="#ff0000" fill="#ff0000" fontWeight="bold">Nuvoton</tspan>
                    {nameLines.map((line, i) => (
                        <tspan key={i} x={labelX} dy="1.2em" stroke="#fff" fill={chipNameColor}>{line}</tspan>
                    ))}
                </text>
            </Tooltip>
            <circle cx="15" cy={520+offset} r="5" stroke="#fff" fill="none" />
        </g>

        {/* <!-- Bottom component --> */}
        {genBottomPinCmpV2(75, 215+offset, bottomPinNo, data, isHideAllFunc)}

        {/* <!-- Top component --> */}
        {genTopPinCmpV2(315+offset, -25, topPinNo, data, isHideAllFunc)}

        {/* <!-- Right component --> */}
        {genRightPinCmpV2(760 + offset, 730 + offset, rightPinNo, data, isHideAllFunc)}

        {/* <!-- Left component --> */}
        {genLeftPinCmpV2(195, 280, leftPinNo, data, isHideAllFunc)}
    </svg>);
};