import { createSlice } from "@reduxjs/toolkit";

const initialState = {};

const r_mfpRegisterName = createSlice({
    name: "r_mfpRegisterName",
    initialState,
    reducers: {
        setMfpRegisterName(state, action) {
            state = action.payload;
            return state;
        }
    }
});

export const { setMfpRegisterName } = r_mfpRegisterName.actions;
export default r_mfpRegisterName.reducer;