import { Checkbox, Form, Input, Modal } from 'antd';
import {
    updatePinName,
    updatePinDescription,
    specialModuleNaming,
    getPropertyNames,
    decimalToHex,
    naturalSort,
} from '../libs/pinconfig-libs';

// ─────────────────────────────────────────────────────────────────────────────
// HTML helpers
// ─────────────────────────────────────────────────────────────────────────────

const CELL  = 'border:1px solid black';
const TABLE = 'border:3px ridge black;';

function tableWrap(caption, rows) {
    return (
        `<table style="${TABLE}" cellpadding="5" cellspacing="5" ` +
        `frame="border" rules="all">` +
        `<caption style="text-align:left">${caption}</caption>` +
        rows +
        `</table>`
    );
}

// ─────────────────────────────────────────────────────────────────────────────
// Section builders
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Captures the chip-view SVG rendered by PinConfigView and embeds it as an
 * inline base-64 image. Returns an empty string when the SVG is not present
 * (e.g. non-Pin mode or unsupported device).
 */
function buildChipViewSection(sectionTitle) {
    const container = document.getElementById('NUC_PinConfiguration_SVG');
    const svg = container?.querySelector('svg');
    if (!svg) return '';
    try {
        // Clone so we don't disturb the live node, and clear the zoom/drag
        // transform that lives on the container (keeps the print at 1:1).
        const clone = svg.cloneNode(true);
        clone.removeAttribute('style');
        // Ensure viewBox exists so width="100%" scales proportionally
        const origW = parseFloat(svg.getAttribute('width'))  || 300;
        const origH = parseFloat(svg.getAttribute('height')) || 300;
        if (!clone.getAttribute('viewBox')) {
            clone.setAttribute('viewBox', `0 0 ${origW} ${origH}`);
        }
        clone.setAttribute('width', '100%');
        clone.removeAttribute('height');
        clone.setAttribute('overflow', 'hidden');
        clone.setAttribute('style', 'display:block');
        if (!clone.getAttribute('xmlns')) {
            clone.setAttribute('xmlns', 'http://www.w3.org/2000/svg');
        }
        const svgString = new XMLSerializer().serializeToString(clone);
        return (
            `<div style="clear:both;overflow:hidden;margin-bottom:16px">` +
            `<h4>${sectionTitle}</h4>` +
            svgString +
            `</div><hr style="clear:both">`
        );
    } catch (e) {
        console.error('ChipView SVG capture failed:', e);
        return '';
    }
}

/** MFP register name → hex value table. */
function buildRegisterSection(sectionTitle) {
    const names = getPropertyNames(g_gpio_MFPs).sort();
    if (!names.length) return '';
    const rows = names.map(n =>
        `<tr>` +
        `<td style="${CELL}">${n}</td>` +
        `<td style="${CELL}">0x${decimalToHex(g_gpio_MFPs[n]).toUpperCase()}</td>` +
        `</tr>`
    ).join('');
    return tableWrap(sectionTitle, rows);
}

/** One row per configured pin (pin number → function). */
function buildPinSection(sectionTitle) {
    let rows = '';
    for (let i = 1; i <= g_NUC_Pin_Total_Number; i++) {
        const desc = g_pinCurrentDescription[i - 1];
        if (!desc) continue;
        rows +=
            `<tr>` +
            `<td style="${CELL}">Pin${updatePinName(i)}</td>` +
            `<td style="${CELL}">${updatePinDescription(desc)}</td>` +
            `</tr>`;
    }
    if (!rows) return '';
    return tableWrap(sectionTitle, rows);
}

/** Pins grouped by module (UART, SPI, …). */
function buildModuleSection(sectionTitle) {
    const byModule = {};
    for (let i = 1; i <= g_NUC_Pin_Total_Number; i++) {
        const desc = g_pinCurrentDescription[i - 1];
        if (!desc) continue;
        let mod = desc.indexOf('_') !== -1 ? desc.slice(0, desc.indexOf('_')) : desc;
        mod = specialModuleNaming(mod);
        const entry = `${updatePinDescription(desc)}(Pin:${updatePinName(i)})`;
        (byModule[mod] ??= []).push(entry);
    }
    const mods = getPropertyNames(byModule);
    if (!mods.length) return '';
    const rows = mods.flatMap(m => {
        byModule[m].sort(naturalSort);
        return byModule[m].map(e =>
            `<tr><td style="${CELL}">${m}</td><td style="${CELL}">${e}</td></tr>`
        );
    }).join('');
    return tableWrap(sectionTitle, rows);
}

/** Pins grouped by GPIO port (PA, PB, …). */
function buildGPIOsection(sectionTitle) {
    const pkgs = NUTOOL_PIN.g_cfg_pkgs?.[NUTOOL_PIN.g_packageNumberIndex];
    if (!pkgs) return '';
    const byGPIO = {};
    for (let i = 1; i <= g_NUC_Pin_Total_Number; i++) {
        const desc = g_pinCurrentDescription[i - 1];
        if (!desc) continue;
        const gpio  = specialModuleNaming(pkgs[i - 1]);
        const entry = `${pkgs[i - 1]}: ${updatePinDescription(desc)}(Pin:${updatePinName(i)})`;
        (byGPIO[gpio] ??= []).push(entry);
    }
    const gpios = getPropertyNames(byGPIO).sort(naturalSort);
    if (!gpios.length) return '';
    const rows = gpios.flatMap(g => {
        byGPIO[g].sort(naturalSort);
        return byGPIO[g].map(e => {
            const colon = e.indexOf(': ');
            const key = e.slice(0, colon);
            const val = e.slice(colon + 2);
            return `<tr><td style="${CELL}">${key}</td><td style="${CELL}">${val}</td></tr>`;
        });
    }).join('');
    return tableWrap(sectionTitle, rows);
}

// ─────────────────────────────────────────────────────────────────────────────
// Main entry point
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Shows the Print Report dialog and, upon confirmation, opens a browser print
 * window with the selected sections. All HTML generation is done here — no
 * dependency on NUTOOL_PIN.printReport / printReport_core.
 *
 * @param {object}   options
 * @param {function} options.t  - i18n translation function from useTranslation()
 */
export const showPrintReportDialog = ({ t }) => {
    let projectName =
        localStorage.getItem('ProjectName') ||
        NUTOOL_PIN.projectName ||
        'MyProject';

    const opt = {
        byChipView: true,
        byRegister: true,
        byPin:      true,
        byModule:   false,
        byGPIO:     false,
    };

    Modal.confirm({
        title:  t('BTN_PRINT_REPORT'),
        width:  500,
        content: (
            <div>
                <Form style={{ marginBottom: 8 }}>
                    <Form.Item label={t('LBL_PROJECT_NAME')}>
                        <Input
                            defaultValue={projectName}
                            onChange={(e) => { projectName = e.target.value; }}
                        />
                    </Form.Item>
                </Form>
                <p>{t('TEXT_PRINT_REPORT_SELECT')}</p>
                <div style={{ display: 'flex', flexDirection: 'column', gap: 4 }}>
                    <Checkbox defaultChecked onChange={(e) => { opt.byChipView = e.target.checked; }}>{t('LBL_PRINT_CHIP_VIEW')}</Checkbox>
                    <Checkbox defaultChecked onChange={(e) => { opt.byRegister = e.target.checked; }}>{t('LBL_PRINT_REGISTER')}</Checkbox>
                    <Checkbox defaultChecked onChange={(e) => { opt.byPin      = e.target.checked; }}>{t('LBL_PRINT_PIN')}</Checkbox>
                    <Checkbox             onChange={(e) => { opt.byModule   = e.target.checked; }}>{t('LBL_PRINT_MODULE')}</Checkbox>
                    <Checkbox             onChange={(e) => { opt.byGPIO     = e.target.checked; }}>{t('LBL_PRINT_GPIO')}</Checkbox>
                </div>
                <p style={{ marginTop: 12, fontSize: 12, color: '#888' }}>
                    {t('TEXT_GENERATE_CODE')}
                </p>
            </div>
        ),
        okText:     t('BTN_CONFIRM'),
        cancelText: t('BTN_LEAVE'),
        onOk: () => {
            try {
                const name = (projectName || '').trim() || 'MyProject';
                _doPrint(name, opt, t);
            } catch (err) {
                console.error(err);
                Modal.error({
                    title:   t('BTN_PRINT_REPORT'),
                    content: err?.message || String(err),
                });
            }
        },
    });
};

// ─────────────────────────────────────────────────────────────────────────────
// Report assembly + window.print()
// ─────────────────────────────────────────────────────────────────────────────

function _doPrint(userProjectName, opt, t) {
    const date = new Date();
    const dateStr =
        `${date.getMonth() + 1}/${date.getDate()}/${date.getFullYear()} ` +
        `${date.getHours()}:${date.getMinutes()}:${date.getSeconds()}`;

    const partNumberText = g_partNumber_package
        ? g_partNumber_package.slice(0, g_partNumber_package.indexOf('('))
        : '';

    const packageNumber = NUTOOL_PIN.getPackageNumber?.() ?? '';

    // ── project summary table ────────────────────────────────────────────────
    let html =
        `<table style="${TABLE}" align="left" cellpadding="5" cellspacing="5" frame="border" rules="all">` +
        `<caption style="text-align:left">${t('LBL_PRINT_PROJECT')}</caption>` +
        `<tr><td style="${CELL}">${t('LBL_PROJECT_NAME').replace(/:$/, '').replace(/：$/, '')}</td><td style="${CELL}">${userProjectName}</td></tr>` +
        `<tr><td style="${CELL}">${t('LBL_PRINT_PROJECT_DATE')}</td><td style="${CELL}">${dateStr}</td></tr>` +
        `</table>`;

    // ── MCU info table ───────────────────────────────────────────────────────
    html +=
        `<table style="${TABLE} margin-left:8px" align="left" cellpadding="5" cellspacing="5" frame="border" rules="all">` +
        `<caption style="text-align:left">${t('LBL_PRINT_MCU')}</caption>` +
        `<tr><td style="${CELL}">${t('LBL_CHIP_SERIES').replace(/:$/, '').replace(/：$/, '')}</td><td style="${CELL}">${g_chipType}</td></tr>` +
        `<tr><td style="${CELL}">${t('LBL_PRINT_MCU_NAME')}</td><td style="${CELL}">${partNumberText}</td></tr>` +
        `<tr><td style="${CELL}">${t('LBL_PRINT_MCU_PACKAGE')}</td><td style="${CELL}">${packageNumber}</td></tr>` +
        `</table>`;

    html += '<div style="clear:both"></div><hr>';

    // ── optional sections ────────────────────────────────────────────────────
    if (opt.byChipView) html += buildChipViewSection(t('LBL_PRINT_CHIP_VIEW'));
    if (opt.byRegister) html += `<div style="break-before:page;page-break-before:always">${buildRegisterSection(t('LBL_PRINT_REGISTER'))}</div>`;

    const rowParts = [];
    if (opt.byPin)    rowParts.push(buildPinSection(t('LBL_PRINT_PIN')));
    if (opt.byModule) rowParts.push(buildModuleSection(t('LBL_PRINT_MODULE')));
    if (opt.byGPIO)   rowParts.push(buildGPIOsection(t('LBL_PRINT_GPIO')));
    if (rowParts.length > 0 && rowParts[0] !== '') {
        html += `<div style="display:flex;gap:8px;align-items:flex-start;flex-wrap:nowrap;break-before:page;page-break-before:always">${rowParts.join('')}</div>`;
    }

    // ── print via hidden iframe ──────────────────────────────────────────────
    // window.open() is blocked inside the VS Code webview, so render the report
    // into an off-screen iframe and print that instead.
    const iframe = document.createElement('iframe');
    iframe.setAttribute('aria-hidden', 'true');
    iframe.style.position = 'fixed';
    iframe.style.right = '0';
    iframe.style.bottom = '0';
    iframe.style.width = '0';
    iframe.style.height = '0';
    iframe.style.border = '0';
    document.body.appendChild(iframe);

    const cleanup = () => {
        if (iframe.parentNode) iframe.parentNode.removeChild(iframe);
    };

    const doc = iframe.contentWindow?.document;
    if (!doc) {
        cleanup();
        Modal.error({ content: 'Unable to create print view.' });
        return;
    }

    doc.open();
    doc.write(
        `<!DOCTYPE html><html><head><title>Print Report</title>` +
        `<style>` +
        `@page { size: A4; margin: 10mm; }` +
        `* { box-sizing: border-box; }` +
        `body { margin: 0; }` +
        `img { max-width: 100%; height: auto; }` +
        `svg { display: block; max-width: 100%; height: auto; overflow: hidden; }` +
        `table { max-width: 100%; }` +
        `</style>` +
        `</head><body>${html}</body></html>`
    );
    doc.close();

    const printIframe = () => {
        try {
            iframe.contentWindow.focus();
            iframe.contentWindow.print();
        } catch (e) {
            console.error('Print failed:', e);
        }
        // Remove the iframe after the print dialog has had time to open.
        setTimeout(cleanup, 1000);
    };

    // Wait for the iframe (and its inline images) to finish loading.
    if (iframe.contentWindow.document.readyState === 'complete') {
        printIframe();
    } else {
        iframe.onload = printIframe;
    }
}
