import { combineReducers } from "redux";
import r_chipType from "../slices/r_chipType";
import r_snippetName from "../slices/r_snippetName";
import r_cfg_perFunctions from "../slices/r_cfg_perFunctions";
import r_partNumber_package from "../slices/r_partNumber_package";
import r_partNumber_type from "../slices/r_partNumber_type";
import r_currentTool from "../slices/r_currentTool";
import r_mfpRegisterName from "../slices/r_mfpRegisterName";
import r_mfpRegisterValue from "../slices/r_mfpRegisterValue";
import r_module_functions from "../slices/r_module_functions";
import r_pinCurrentDescription from "../slices/r_pinCurrentDescription";
import r_pkg from "../slices/r_pkg";
import r_allStatus from "../slices/r_allStatus";
import r_settings from "../slices/r_settings";

const reducers = combineReducers({
  r_chipType,
  r_snippetName,
  r_cfg_perFunctions,
  r_partNumber_package,
  r_partNumber_type,
  r_currentTool,
  r_mfpRegisterName,
  r_mfpRegisterValue,
  r_module_functions,
  r_pinCurrentDescription,
  r_pkg,
  r_allStatus,
  ...r_settings,
});

export default reducers;