/* global NUTOOL_PINVIEW */
import { createSlice } from "@reduxjs/toolkit";

// const vscode = typeof acquireVsCodeApi !== 'undefined' ? acquireVsCodeApi() : { postMessage: () => {} };

const r_settings_hideAllPin = createSlice({
    name: "r_settings_hideAllPin",
    initialState: true,
    reducers: {
        setSettings_hideAllPin(state, action) {
            state = action.payload;
            return state;
        }
    }
});

const r_settings_hideLogs = createSlice({
    name: "r_settings_hideLogs",
    initialState: true,
    reducers: {
        setSettings_hideLogs(state, action) {
            state = action.payload;
            return state;
        }
    }
});

const initialFreq = {
    intervalId: null,
    frequency: 2000, // 默认频率
};

const r_settings_freq = createSlice({
    name: "r_settings_freq",
    initialState: initialFreq,
    reducers: {
        setSettings_freq(state, action) {
            state.frequency = action.payload;
            // vscode.postMessage({ type: 'setIntervalTime', value: state.frequency });
            return state;
        }
    }
});

const r_logs = createSlice({
    name: "r_logs",
    initialState: "",
    reducers: {
        setLogs(state, action) {
            state += action.payload+'<br>';
            return state;
        }
    }
});

export const { setSettings_hideAllPin } = r_settings_hideAllPin.actions;
export const { setSettings_hideLogs } = r_settings_hideLogs.actions;
export const { setSettings_freq } = r_settings_freq.actions;
export const { setLogs } = r_logs.actions;

const reducers = {
    r_settings_hideAllPin: r_settings_hideAllPin.reducer,
    r_settings_hideLogs: r_settings_hideLogs.reducer,
    r_settings_freq: r_settings_freq.reducer,
    r_logs: r_logs.reducer,
};

export default reducers;