import React, { useEffect } from 'react'
import { useDispatch, useSelector } from "react-redux";
import { useTranslation } from 'react-i18next';
import {
	Form,
	Select,
} from 'antd';

// import { DEFAULT_VALUE } from '../content-web-constants.js';
import {
	initializeAll,
	fetchOtherContentJS,
// 	replacejscssfile,
// 	chipSeriesToChipType,
} from '../content-web-commonLib.js';


import {
	decideNewChipType,
	refresh,
	decideNUC_Pin_Total_Side_Number,
	goToResetValueState,
} from '../libs/pinconfig-libs';

// import { setChipType } from "../store/slices/r_chipType";
import { set_partNumber_package } from "../store/slices/r_partNumber_package";
import { set_partNumber_type } from "../store/slices/r_partNumber_type";
import { setSnippetName } from "../store/slices/r_snippetName";
import { set_cfg_perFunctions } from "../store/slices/r_cfg_perFunctions";
import { setMfpRegisterName } from "../store/slices/r_mfpRegisterName";
import { setMfpRegisterValue } from "../store/slices/r_mfpRegisterValue";
import { set_module_functions } from "../store/slices/r_module_functions.js";
import { setPinCurrentDescription } from "../store/slices/r_pinCurrentDescription.js";

// const { PART_NUMBER } = DEFAULT_VALUE;

const PartNo = (props) => {
	const { t } = useTranslation();
	const r_chipType = useSelector((state) => state.r_chipType);
	const r_partNumber_package = useSelector((state) => state.r_partNumber_package);
	const dispatch = useDispatch();

	// From afterMCUchange()
	const handleChangePartNo = async (value, node, preNode, bb) => {
		const oldChipType = decideNewChipType(r_partNumber_package);
		const newChipType = decideNewChipType(value);
		
		if (oldChipType !== newChipType) {
			await fetchOtherContentJS(newChipType);
		}
		initializeAll();
		g_partNumber_package = value;
		NUTOOL_PIN.decidepackageNumber();
		decideNUC_Pin_Total_Side_Number();
		dispatch(set_partNumber_package(value));
		// dispatch(set_partNumber_type(node.type));
		// dispatch(set_cfg_perFunctions([]));
		// dispatch(setSnippetName(""));
		refresh();
		goToResetValueState();
		dispatch(setMfpRegisterName(Object.assign([], g_gpio_MFPs)));
		dispatch(set_module_functions(Object.assign([], g_module_functions)));
		dispatch(setPinCurrentDescription(
			Object.assign([],
				NUTOOL_PIN.g_cfg_pkgs[NUTOOL_PIN.g_packageNumberIndex].map(() => "")
			)
		));
	};
	EXPORT_REACT.handleChangePartNo = handleChangePartNo;

	// Trigger handleChangePartNo on initial render
	useEffect(() => {
		if (r_partNumber_package && NUTOOL_PIN.g_cfg_chips.length > 0) {
			const initialChip = NUTOOL_PIN.g_cfg_chips.find(chip => 
				chip.name + "(" + chip.pkg + ")" === r_partNumber_package
			);
			if (initialChip) {
				handleChangePartNo(r_partNumber_package, { type: initialChip.type });
			}
		}
	}, []); // Empty dependency array ensures this runs only once on mount

	useEffect(() => {
		
	}, [r_partNumber_package]);

	return (
		<Form layout="vertical">

			<Form.Item label={<b>{t("LBL_PART_NO")}</b>}>
				<Select
					defaultValue={r_partNumber_package}
					value={r_partNumber_package}
					onChange={handleChangePartNo}
				>
					{/* From buildMCUselect() */}
					{ NUTOOL_PIN.g_cfg_chips.map((g_cfg_chip) => 
						<Select.Option
							key={g_cfg_chip.name || ""}
							value={g_cfg_chip.name + "(" + g_cfg_chip.pkg+")"}
							type={g_cfg_chip.type || ""}
						>
							{g_cfg_chip.name + "(" + g_cfg_chip.pkg+")"}
						</Select.Option>
					)}
				</Select>
			</Form.Item>
		</Form>
	);
};

export default PartNo;