import { createSlice } from "@reduxjs/toolkit";

function sortNumber(a, b) { return a.pin_no - b.pin_no }

const r_allStatus = createSlice({
    name: "r_allStatus",
    initialState: {},
    reducers: {
        setAllStatus(state, action) {
            const newState = {
                ...action.payload,
                pins: [...(action.payload.pins || [])].sort(sortNumber)
            };
            console.dir(newState);
            return newState;
        }
    }
});

export const { setAllStatus } = r_allStatus.actions;
export default r_allStatus.reducer;
