import React, { useEffect, useMemo, useRef, useState } from 'react';
import { Alert, Checkbox, Modal, Radio, Select, Space, Tooltip, Typography } from 'antd';
import { useSelector } from 'react-redux';
import { useTranslation } from 'react-i18next';

import '../libs/autoAssign';
import { naturalSort, updatePinName } from '../libs/pinconfig-libs';

const { Text } = Typography;

const removeItem = (array, target) => {
    const index = array.indexOf(target);
    if (index > -1) {
        array.splice(index, 1);
    }
};

const pushUnique = (array, value) => {
    if (!array.includes(value)) {
        array.push(value);
    }
};

const pause = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
const TYPE_YIELD_INTERVAL = 1024;
const CHANNEL_YIELD_INTERVAL = 128;

const cloneDeep = (value) => {
    return typeof structuredClone === 'function'
        ? structuredClone(value)
        : JSON.parse(JSON.stringify(value));
};

const isGPIOModule = (pinName) => {
    return typeof pinName === 'string' && /^[P][A-Z0-9]$/.test(pinName);
};

const buildOptions = (max, selected = 1, label = '') => {
    return Array.from({ length: max }, (_, index) => {
        const value = index + 1;
        const optionLabel = label
            ? `${value} ${value === 1 ? label : `${label}s`}`
            : `${value}`;

        return {
            value,
            label: optionLabel,
            selected: value === selected,
        };
    });
};

const buildModuleJsonData = (moduleFunctions, pinCurrentDescription) => {
    if (!moduleFunctions) {
        return [];
    }

    const isArrayIndexKey = (key) => String(Number(key)) === key;
    let moduleNames = [];

    if (Array.isArray(moduleFunctions)) {
        moduleNames = Object.keys(moduleFunctions).filter((key) => !isArrayIndexKey(key));
    }
    else if (typeof moduleFunctions === 'object') {
        moduleNames = Object.keys(moduleFunctions);
    }

    const modulePinsMap = globalThis?.g_module_pins || {};
    const disabledLeafNodes = [];

    const getSubNodeBaseName = (subNodeName) => {
        if (typeof subNodeName !== 'string') {
            return '';
        }
        const pinIndex = subNodeName.lastIndexOf('_Pin');
        return pinIndex > -1 ? subNodeName.slice(0, pinIndex) : subNodeName;
    };

    const getPinWithStatusLabel = (subNodeName) => {
        const pinIndex = subNodeName.lastIndexOf('_Pin');
        const baseName = pinIndex > -1 ? subNodeName.slice(0, pinIndex) : subNodeName;
        const pin = pinIndex > -1 ? subNodeName.slice(pinIndex + 4) : '';
        return `${baseName} (Pin:${updatePinName(pin)})`;
    };

    moduleNames.sort(naturalSort);

    const jsonDataArray = moduleNames.map((moduleName) => {
        const functions = moduleFunctions[moduleName];
        const modulePins = Array.isArray(modulePinsMap[moduleName]) ? modulePinsMap[moduleName] : [];
        const subNodeNameArray = [];

        if (Array.isArray(functions) && modulePins.length > 0) {
            for (let j = 0, maxJ = modulePins.length; j < maxJ; j += 1) {
                const subNodeName = functions[j];
                if (!subNodeName) {
                    continue;
                }
                subNodeNameArray.push(`${String(subNodeName)}_Pin${modulePins[j]}`);
            }
        }
        else if (Array.isArray(functions)) {
            functions.forEach((functionName) => {
                if (!functionName) {
                    return;
                }
                subNodeNameArray.push(String(functionName));
            });
        }

        subNodeNameArray.sort(naturalSort);

        const skippedIndexSet = new Set();
        const children = [];

        for (let j = 0; j < subNodeNameArray.length; j += 1) {
            if (skippedIndexSet.has(j)) {
                continue;
            }

            const subNodeName = subNodeNameArray[j];
            const baseName = getSubNodeBaseName(subNodeName);
            const identicalIndexes = [];

            for (let k = j + 1; k < subNodeNameArray.length; k += 1) {
                if (getSubNodeBaseName(subNodeNameArray[k]) === baseName) {
                    identicalIndexes.push(k);
                    skippedIndexSet.add(k);
                }
            }

            if (identicalIndexes.length === 0) {
                children.push({
                    data: getPinWithStatusLabel(subNodeName),
                    attr: { id: `${subNodeName}` },
                    children: [],
                });
            }
            else {
                const groupChildren = [j, ...identicalIndexes].map((idx) => {
                    const name = subNodeNameArray[idx];
                    disabledLeafNodes.push(name);
                    return {
                        data: getPinWithStatusLabel(name),
                        attr: { id: `${name}` },
                        children: [],
                    };
                });

                children.push({
                    data: baseName,
                    attr: { id: `${baseName}_Intermediate` },
                    children: groupChildren,
                });
            }
        }

        return {
            data: moduleName,
            attr: { id: `${moduleName}_Root` },
            children,
        };
    });

    return {
        jsonDataArray,
        disabledLeafNodes,
        pinCurrentDescription,
    };
};

const getLeafChecked = (leafId, pinCurrentDescription) => {
    const match = String(leafId).match(/^(.*)_Pin(\d+)$/);
    if (!match) {
        return false;
    }
    const [, moduleName, pinNo] = match;
    return pinCurrentDescription[Number(pinNo) - 1] === moduleName;
};

const getChildStatus = (child, pinCurrentDescription) => {
    if (Array.isArray(child.children) && child.children.length > 0) {
        const checkedLeafChildren = child.children.filter((leaf) => getLeafChecked(leaf.attr.id, pinCurrentDescription));
        return {
            checked: checkedLeafChildren.length > 0,
            undetermined: checkedLeafChildren.length > 0,
            checkedLeafIds: checkedLeafChildren.map((leaf) => leaf.attr.id),
        };
    }

    const checked = getLeafChecked(child.attr.id, pinCurrentDescription);
    return {
        checked,
        undetermined: false,
        checkedLeafIds: checked ? [child.attr.id] : [],
    };
};

const PinAutoAssignmentModal = ({ open, onClose }) => {
    const { t } = useTranslation();
    const r_module_functions = useSelector((state) => state.r_module_functions);
    const r_pinCurrentDescription = useSelector((state) => state.r_pinCurrentDescription);
    const [confirmLoading, setConfirmLoading] = useState(false);
    const [checkedRootIds, setCheckedRootIds] = useState({});
    const [checkedTypeKeys, setCheckedTypeKeys] = useState({});
    const [checkedChannelIds, setCheckedChannelIds] = useState({});
    const [groupCounts, setGroupCounts] = useState({});
    const [ebiMode, setEbiMode] = useState('EBI_M');
    const [progressVisible, setProgressVisible] = useState(false);
    const [progressNow, setProgressNow] = useState('0');
    const [progressTotal, setProgressTotal] = useState('0');
    const interruptRef = useRef(false);
    const runningRef = useRef(false);

    const preparedData = useMemo(() => {
        const autoAssign = globalThis?.NUTOOL_PIN?.autoAssign;
        if (!autoAssign?.getg_modulesBase) {
            return {
                ready: false,
                items: [],
                modulesTree: [],
                modulesType: {},
                disabledLeafNodes: [],
                assignmentTemplate: null,
            };
        }

        const built = buildModuleJsonData(r_module_functions, r_pinCurrentDescription);
        const jsonDataArray = built?.jsonDataArray || [];
        const disabledLeafNodes = built?.disabledLeafNodes || [];
        const { modulesTree, modulesType } = autoAssign.getg_modulesBase(jsonDataArray);
        const typeRendered = new Set();
        const items = [];

        const assignmentTemplate = {
            type: cloneDeep(modulesType),
            channel: {},
            root: {
                checkedId: [],
                uncheckedId: [],
                undeterminedId: [],
                checkedTypeKey: [],
                uncheckedTypeKey: [],
                checkedCHId: [],
                uncheckedCHId: [],
            },
            module: {
                checkedId: [],
                undeterminedId: [],
            },
            result: [],
        };

        r_pinCurrentDescription.forEach((moduleName) => {
            if (!moduleName) {
                return;
            }
            const target = `${String(moduleName.slicePriorToX("_"))}_Root`;
            Object.keys(assignmentTemplate.type).forEach((key) => {
                if (!Array.isArray(assignmentTemplate.type[key])) {
                    return;
                }
                assignmentTemplate.type[key] = assignmentTemplate.type[key].filter((value) => value !== target);
            });
        });

        modulesTree.forEach((rootNode) => {
            const childStatuses = rootNode.children
                .filter((child) => child.isDefault)
                .map((child) => ({ child, ...getChildStatus(child, r_pinCurrentDescription) }));
            const selectedCount = childStatuses.filter((status) => status.checked).length;
            const totalCount = childStatuses.length;
            const isChecked = totalCount > 0 && selectedCount === totalCount;
            const isUndetermined = selectedCount > 0 && selectedCount < totalCount;
            const key = `${rootNode.module}_type_${rootNode.typeIdx}`;
            const typeLabel = rootNode.typeIdx === 1 ? '' : ` (Type ${rootNode.typeIdx})`;
            const tip = childStatuses.map(({ child }) => autoAssign.extractChildLabel(rootNode.data, child.data)).join('\n');

            if (isGPIOModule(rootNode.data) && !(isChecked || isUndetermined)) {
                return;
            }

            if (isChecked || isUndetermined) {
                pushUnique(assignmentTemplate.root[isUndetermined ? 'undeterminedId' : 'checkedId'], rootNode.attr.id);
                childStatuses.forEach(({ child, checked, checkedLeafIds }) => {
                    if (checked && Array.isArray(child.children) && child.children.length > 0) {
                        checkedLeafIds.forEach((id) => pushUnique(assignmentTemplate.module.checkedId, id));
                    }
                    else if (checked) {
                        pushUnique(assignmentTemplate.module.checkedId, child.attr.id);
                    }
                });

                items.push({
                    kind: 'fixed',
                    id: rootNode.attr.id,
                    label: `${rootNode.module}${typeLabel}`,
                    status: isUndetermined ? 'indeterminate' : 'checked',
                    children: childStatuses
                        .filter(({ checked }) => checked)
                        .map(({ child }) => ({
                            id: child.attr.id,
                            label: autoAssign.extractChildLabel(rootNode.data, child.data),
                        })),
                });
                return;
            }

            const defaultChildren = rootNode.children.filter((child) => child.isDefault);
            if (defaultChildren.length === 0) {
                return;
            }

            if (rootNode.attr.id === 'EBI_Root') {
                assignmentTemplate.root.uncheckedId.push(rootNode.attr.id);
                items.push({
                    kind: 'ebi',
                    id: rootNode.attr.id,
                    label: `${rootNode.module}${typeLabel}`,
                });
                return;
            }

            if (rootNode.isChannel) {
                assignmentTemplate.root.uncheckedCHId.push(rootNode.attr.id);
                assignmentTemplate.channel[rootNode.attr.id] = defaultChildren.map((child) => child.attr.id);
                items.push({
                    kind: 'channel',
                    id: rootNode.attr.id,
                    label: rootNode.module,
                    max: defaultChildren.length,
                    tip,
                });
                return;
            }

            const availableTypeRoots = assignmentTemplate.type[key] || [];
            if (availableTypeRoots.length > 1) {
                if (typeRendered.has(key)) {
                    return;
                }
                typeRendered.add(key);
                assignmentTemplate.root.uncheckedTypeKey.push(key);
                assignmentTemplate.root.uncheckedId.push(...availableTypeRoots);
                items.push({
                    kind: 'group',
                    id: key,
                    label: `${rootNode.module}${typeLabel}`,
                    max: availableTypeRoots.length,
                    tip,
                });
                return;
            }

            assignmentTemplate.root.uncheckedId.push(rootNode.attr.id);
            items.push({
                kind: 'single',
                id: rootNode.attr.id,
                label: `${rootNode.module}${typeLabel}`,
                tip,
            });
        });

        return {
            ready: true,
            items,
            modulesTree,
            modulesType,
            disabledLeafNodes,
            assignmentTemplate,
        };
    }, [r_module_functions, r_pinCurrentDescription]);

    useEffect(() => {
        if (!open) {
            return;
        }

        const initialGroupCounts = {};
        preparedData.items.forEach((item) => {
            if (item.kind === 'group' || item.kind === 'channel') {
                initialGroupCounts[item.id] = 1;
            }
        });

        setCheckedRootIds({});
        setCheckedTypeKeys({});
        setCheckedChannelIds({});
        setGroupCounts(initialGroupCounts);
        setEbiMode('EBI_M');
    }, [open, preparedData.items]);

    const handleApply = async () => {
        if (runningRef.current) {
            return;
        }

        runningRef.current = true;
        interruptRef.current = false;
        let lastErrMsg = '';
        if (!preparedData.ready || !preparedData.assignmentTemplate) {
            runningRef.current = false;
            return;
        }

        if (typeof globalThis.triggerModuleTreeCheck !== 'function') {
            EXPORT_REACT?.warning?.(t('BTN_AUTO_ASSIGN'), 'triggerModuleTreeCheck is not ready.');
            runningRef.current = false;
            return;
        }

        const autoAssign = globalThis.NUTOOL_PIN.autoAssign;
        const modulesById = Object.fromEntries(preparedData.modulesTree.map((item) => [item.attr.id, item]));
        const pickCountMap = {};
        preparedData.items.forEach((item) => {
            if (item.kind === 'group' || item.kind === 'channel') {
                pickCountMap[item.id] = Number(groupCounts[item.id] || 1);
            }
        });

        const handleRootCheckboxChange = (assignment, id, checked) => {
            const rootNode = modulesById[id];
            if (!rootNode) {
                return;
            }

            const ebiAllowed = id === 'EBI_Root'
                ? new Set(autoAssign?.priority?.L3?.[ebiMode] || [])
                : null;

            rootNode.children.forEach((child) => {
                if (!child.isDefault) {
                    return;
                }

                if (ebiAllowed) {
                    if (!ebiAllowed.has(child.data.split('(Pin')[0].trim())) {
                        return;
                    }
                }

                const isIntermediate = child.attr.id.includes('_Intermediate');
                if (checked) {
                    if (isIntermediate) {
                        pushUnique(assignment.module.undeterminedId, child.attr.id);
                    }
                    else {
                        pushUnique(assignment.module.checkedId, child.attr.id);
                    }
                }
                else if (isIntermediate) {
                    removeItem(assignment.module.undeterminedId, child.attr.id);
                }
                else {
                    removeItem(assignment.module.checkedId, child.attr.id);
                }
            });
        };

        const setAssignmentResult = (assignment, target) => {
            const match = String(target).match(/Pin(\d+)/);
            if (!match) {
                return;
            }

            const pinNum = Number(match[1]);
            const index = pinNum - 1;
            const assigned = assignment.result[index];

            if (!assigned) {
                assignment.result[index] = target;
                return;
            }

            const stripPin = (value) => String(value).replace(`_Pin${pinNum}`, '');
            const moduleNew = stripPin(target);
            const moduleOld = stripPin(assigned);

            throw new Error(`"${moduleNew}" conflict occurred. Pin${pinNum} is already assigned to "${moduleOld}".`);
        };

        const collectAvailablePins = (assignment, undeterminedIds) => {
            undeterminedIds.forEach((id) => {
                const rootId = id.slicePriorToX("_") + "_Root";
                const rootNode = modulesById[rootId];
                const intermediateNode = rootNode?.children?.find((child) => child.attr.id === id);
                (intermediateNode?.children || []).forEach((leafNode) => {
                    const leafNodeId = leafNode.attr.id;
                    const match = leafNodeId.match(/Pin(\d+)/);
                    if (!match) {
                        return;
                    }

                    const pinNum = parseInt(match[1], 10);
                    const index = pinNum - 1;
                    if (assignment.result[index] !== undefined) {
                        return;
                    }

                    const key = leafNodeId.split('_Pin')[0];
                    assignment.candidatePins[key] ||= [];
                    if (!assignment.candidatePins[key].includes(index)) {
                        assignment.candidatePins[key].push(index);
                    }
                });
            });
        };

        const allocatePins = (assignment) => {
            let result = autoAssign.allocateUniquePin(assignment.result, assignment.candidatePins);
            assignment.result = result.result;
            assignment.candidatePins = result.candidatePins;

            result = autoAssign.allocatePinsRecursiveDebug(assignment.result, assignment.candidatePins);
            assignment.result = result.result;
            assignment.candidatePins = result.candidatePins;
        };

        setConfirmLoading(true);
        // Let React render loading state so Cancel can respond immediately.
        await pause(0);

        try {
            const assignmentBase = cloneDeep(preparedData.assignmentTemplate);

            const selectedTypeKeys = Object.keys(checkedTypeKeys).filter((key) => checkedTypeKeys[key]);
            const selectedChannelIds = Object.keys(checkedChannelIds).filter((key) => checkedChannelIds[key]);
            const selectedRootIds = Object.keys(checkedRootIds).filter((id) => checkedRootIds[id]);
            const typeCombinationCount = autoAssign.countAllTypeCombinations(
                assignmentBase.type,
                selectedTypeKeys,
                { pickCountMap }
            );
            const channelCombinationCount = autoAssign.countAllTypeCombinations(
                assignmentBase.channel,
                selectedChannelIds,
                { pickCountMap }
            );

            let finished = false;
            let finalAssignment = null;
            let index = 0;
            const channelWeight = Math.max(channelCombinationCount, 1);
            const totalProgress = Math.max(typeCombinationCount, 1) * channelWeight;

            setProgressNow('0');
            setProgressTotal(totalProgress.toLocaleString());
            setProgressVisible(true);

            const typeIterator = autoAssign.listAllTypeCombinations(
                assignmentBase.type,
                selectedTypeKeys,
                { flat: true, pickCountMap }
            );
            const channelIteratorFactory = (assignmentState) => autoAssign.listAllTypeCombinations(
                assignmentState.channel,
                selectedChannelIds,
                { flat: true, pickCountMap }
            );
            console.log(`Overall Combinations: ${typeCombinationCount} x ${channelCombinationCount} = ${typeCombinationCount * channelCombinationCount}`);

            for (const combo of typeIterator) {
                const currentAssignment = cloneDeep(assignmentBase);
                currentAssignment.candidatePins = {};

                try {
                    if (interruptRef.current) {
                        break;
                    }

                    if (index % TYPE_YIELD_INTERVAL === 0) {
                        await pause(0);
                        setProgressNow((index * channelWeight).toLocaleString());
                    }

                    selectedRootIds.forEach((id) => handleRootCheckboxChange(currentAssignment, id, true));

                    combo.forEach((id) => handleRootCheckboxChange(currentAssignment, id, true));
                    currentAssignment.module.checkedId.forEach((id) => setAssignmentResult(currentAssignment, id));
                    collectAvailablePins(currentAssignment, currentAssignment.module.undeterminedId);

                    const missingId = currentAssignment.module.undeterminedId
                        .map((id) => id.replace('_Intermediate', ''))
                        .filter((key) => !(key in currentAssignment.candidatePins));
                    if (missingId.length > 0) {
                        throw new Error(`Some modules have no available pins: ${missingId.join(', ')}`);
                    }

                    allocatePins(currentAssignment);

                    if (Object.keys(currentAssignment.candidatePins).length === 0) {
                        let channelIndex = 0;
                        for (const combo2 of channelIteratorFactory(currentAssignment)) {
                            if (interruptRef.current) {
                                break;
                            }

                            if (channelIndex % 1024 === 0) {
                                await pause(0);
                                setProgressNow((index * channelWeight + channelIndex).toLocaleString());
                            }

                            const assignment2 = cloneDeep(currentAssignment);
                            const undeterminedIds = [];

                            try {
                                combo2.forEach((id) => {
                                    if (id.includes('_Intermediate')) {
                                        undeterminedIds.push(id);
                                    }
                                    else {
                                        setAssignmentResult(assignment2, id);
                                    }
                                });

                                assignment2.candidatePins = {};
                                collectAvailablePins(assignment2, undeterminedIds);
                                allocatePins(assignment2);

                                if (Object.keys(assignment2.candidatePins).length === 0) {
                                    finalAssignment = assignment2;
                                    finished = true;
                                    break;
                                }
                            }
                            catch (error) {
                                // continue searching next channel combination
                                // console.error('Error in channel combination:', error);
                                lastErrMsg = error.message;
                            }

                            channelIndex += 1;
                        }

                        if (interruptRef.current) {
                            break;
                        }

                        if (!selectedChannelIds.length) {
                            finalAssignment = currentAssignment;
                            finished = true;
                        }
                    }
                }
                catch (error) {
                    // continue searching next type combination
                    // console.error('Error in type combination:', error);
                    lastErrMsg = error.message;
                }

                index += 1;

                if (finished) {
                    break;
                }
            }

            setProgressNow(totalProgress.toLocaleString());
            setProgressVisible(false);
            await pause(0);

            if (!finished || !finalAssignment) {
                if (interruptRef.current) {
                    return;
                }
                EXPORT_REACT?.warning?.(
                    t('BTN_AUTO_ASSIGN'),
                    `Auto pin assignment failed.\n(${lastErrMsg})`
                );
                return;
            }

            const assignedNodes = finalAssignment.result.filter(Boolean);
            for (let i = 0; i < assignedNodes.length; i += 1) {
                await globalThis.triggerModuleTreeCheck(assignedNodes[i], true);
            }

            onClose?.();
        }
        finally {
            setProgressVisible(false);
            setConfirmLoading(false);
            runningRef.current = false;
        }
    };

    return (
        <>
            <Modal
                title={t('BTN_AUTO_ASSIGN')}
                open={open}
                onCancel={() => {
                    interruptRef.current = true;
                    onClose?.();
                }}
                onOk={handleApply}
                confirmLoading={confirmLoading}
                width={560}
                destroyOnHidden={false}
            >
                {!preparedData.ready ? (
                    <Alert
                        type="warning"
                        showIcon
                        message="Auto assignment data is not ready."
                    />
                ) : (
                    <Space direction="vertical" size={8} style={{ width: '100%', maxHeight: 420, overflow: 'auto' }}>
                        {preparedData.items.map((item) => {
                            if (item.kind === 'fixed') {
                                return (
                                    <div key={item.id}>
                                        <Checkbox checked disabled indeterminate={item.status === 'indeterminate'}>
                                            {item.label}
                                        </Checkbox>
                                        {item.children.map((child) => (
                                            <div key={child.id} style={{ marginLeft: 24 }}>
                                                <Checkbox checked disabled>{child.label}</Checkbox>
                                            </div>
                                        ))}
                                    </div>
                                );
                            }

                            if (item.kind === 'ebi') {
                                return (
                                    <div key={item.id}>
                                        <Space wrap>
                                            <Checkbox
                                                checked={!!checkedRootIds[item.id]}
                                                onChange={(event) => {
                                                    setCheckedRootIds((prev) => ({ ...prev, [item.id]: event.target.checked }));
                                                }}
                                            >
                                                {item.label}
                                            </Checkbox>
                                            <Radio.Group
                                                value={ebiMode}
                                                onChange={(event) => setEbiMode(event.target.value)}
                                                disabled={!checkedRootIds[item.id]}
                                            >
                                                <Radio value="EBI_M">Multiplex Mode</Radio>
                                                <Radio value="EBI_S">Separate Mode</Radio>
                                            </Radio.Group>
                                        </Space>
                                    </div>
                                );
                            }

                            const checked = item.kind === 'group'
                                ? !!checkedTypeKeys[item.id]
                                : item.kind === 'channel'
                                    ? !!checkedChannelIds[item.id]
                                    : !!checkedRootIds[item.id];

                            const onCheckedChange = (value) => {
                                if (item.kind === 'group') {
                                    setCheckedTypeKeys((prev) => ({ ...prev, [item.id]: value }));
                                    return;
                                }
                                if (item.kind === 'channel') {
                                    setCheckedChannelIds((prev) => ({ ...prev, [item.id]: value }));
                                    return;
                                }
                                setCheckedRootIds((prev) => ({ ...prev, [item.id]: value }));
                            };

                            const labelNode = item.tip ? (
                                <Tooltip title={<span style={{ whiteSpace: 'pre-line' }}>{item.tip}</span>}>
                                    <Text>{item.label}</Text>
                                </Tooltip>
                            ) : item.label;

                            return (
                                <div key={item.id}>
                                    <Space wrap>
                                        <Checkbox
                                            checked={checked}
                                            onChange={(event) => onCheckedChange(event.target.checked)}
                                        >
                                            {labelNode}
                                        </Checkbox>
                                        {(item.kind === 'group' || item.kind === 'channel') ? (
                                            <Select
                                                style={{ width: 110 }}
                                                disabled={!checked}
                                                value={groupCounts[item.id] || 1}
                                                onChange={(value) => setGroupCounts((prev) => ({ ...prev, [item.id]: value }))}
                                                options={buildOptions(item.max, groupCounts[item.id] || 1, item.kind === 'channel' ? 'channel' : '')}
                                            />
                                        ) : null}
                                    </Space>
                                </div>
                            );
                        })}
                    </Space>
                )}
            </Modal>

            <Modal
                title="Processing"
                open={progressVisible}
                onCancel={() => {
                    interruptRef.current = true;
                    setProgressVisible(false);
                }}
                cancelText="Cancel"
                okButtonProps={{ style: { display: 'none' } }}
                closable={true}
                maskClosable={false}
            >
                <p>Processing: {progressNow} / {progressTotal}</p>
            </Modal>
        </>
    );
};

export default PinAutoAssignmentModal;
