import { Checkbox, Input, Modal, Radio, Table } from 'antd';
import { useState } from 'react';
import { saveAs } from 'file-saver';

import { get_pin_descriptions, setReviewReportTable, isElectron } from '../libs/pinconfig-libs';

/**
 * Dialog content component — manages its own state so hooks work inside Modal.confirm.
 */
function NuCADDialogContent({ t }) {
    const [showTable, setShowTable] = useState(false);
    const [tableData, setTableData] = useState([]);

    const handleUserDefinedCheck = (e) => {
        if (e.target.checked) {
            const data = get_pin_descriptions();
            setTableData(Array.isArray(data) ? data : []);
            setShowTable(true);
        } else {
            setShowTable(false);
        }
    };

    const columns = [
        { title: t('TBL_COL_PIN'),         dataIndex: 'pin',         key: 'pin',         width: 55 },
        { title: t('TBL_COL_PIN_NAME'),    dataIndex: 'pinName',     key: 'pinName',     width: 90 },
        { title: t('TBL_COL_DESCRIPTION'), dataIndex: 'description', key: 'description' },
        {
            title: t('TBL_COL_USER_DEFINED'),
            dataIndex: 'userDefined',
            key: 'userDefined',
            width: 140,
            render: (text, record) => (
                <Input
                    defaultValue={text}
                    maxLength={30}
                    title={t('TBL_TOOLTIP_USER_DEFINED')}
                    onChange={(e) => {
                        const val = e.target.value;
                        if (/^[a-zA-Z0-9 _]*$/.test(val)) {
                            setReviewReportTable(
                                record.pinNumber,
                                record.description,
                                val
                            );
                        }
                    }}
                />
            ),
        },
    ];

    const emptyText = showTable && tableData.length === 0
        ? t('TBL_EMPTY_USER_DEFINED')
        : undefined;

    return (
        <div>
            <p>{t('TEXT_RUN_TOOL_SELECT')}</p>
            <Radio defaultChecked>OrCAD</Radio>
            <br /><br />
            <Checkbox onChange={(e) => { NUTOOL_PIN.nuCadUseNCPin = e.target.checked; }}>
                {t('TEXT_RUN_TOOL_USE_NC_PIN')}
            </Checkbox>
            <br />
            <Checkbox onChange={handleUserDefinedCheck}>
                {t('TEXT_RUN_TOOL_USER_DEFINED')}
            </Checkbox>
            {showTable && (
                <Table
                    dataSource={tableData}
                    columns={columns}
                    rowKey="pinNumber"
                    size="small"
                    pagination={false}
                    scroll={{ y: 240 }}
                    style={{ marginTop: 8 }}
                    locale={{ emptyText: emptyText || t('TBL_EMPTY_USER_DEFINED') }}
                />
            )}
            {!showTable && (
                <p style={{ marginTop: 12, fontSize: 12, color: '#888' }}>
                    {t('TEXT_RUN_TOOL_NOTICE')}
                </p>
            )}
        </div>
    );
}

/**
 * Shows the Run NuCAD dialog and, upon confirmation, generates a .csv file
 * and optionally sends the runNuCAD IPC event in Electron.
 *
 * @param {object}   options
 * @param {function} options.t           - i18n translation function
 * @param {string}   options.partNumber  - current part number (r_partNumber_package)
 */
export const showRunNuCADDialog = ({ t, partNumber }) => {
    NUTOOL_PIN.nuCadUseNCPin = false;

    const toolName = (
        typeof NUTOOL_PIN.g_anotherNameForNuCAD === 'string' &&
        NUTOOL_PIN.g_anotherNameForNuCAD.indexOf('CAD') !== -1
    )
        ? NUTOOL_PIN.g_anotherNameForNuCAD
        : 'NuCAD';

    Modal.confirm({
        title: t('BTN_RUN_NUCAD'),
        width: 560,
        content: <NuCADDialogContent t={t} />,
        okText: t('BTN_CONFIRM'),
        cancelText: t('BTN_LEAVE'),
        onOk: () => {
            try {
                get_pin_descriptions();

                const year = new Date().getFullYear();
                const now = new Date();
                const briefName = g_briefName || '';
                const companyName = g_copyrightCompanyName || '';

                const textCAD =
                    `/****************************************************************************\r\n`
                    + ` * @file     ${toolName}.csv\r\n`
                    + ` * @Date     ${now}\r\n`
                    + ` * @brief    ${briefName} generated code file\r\n`
                    + ` *\r\n`
                    + ` * SPDX-License-Identifier: Apache-2.0\r\n`
                    + ` *\r\n`
                    + ` * Copyright (C) 2013-${year}${companyName} All rights reserved.\r\n`
                    + `*****************************************************************************/\r\n`
                    + `MCU:${partNumber}\r\n`
                    + `${g_pin_descriptions || ''}`
                    + (NUTOOL_PIN.nuCadUseNCPin ? `UseNCPin\r\n` : ``)
                    + `/*** (C) COPYRIGHT 2013-${year}${companyName} ***/\r\n`;

                saveAs(
                    new Blob([textCAD], { type: 'text/plain;charset=utf-8' }),
                    `${toolName}.csv`
                );

                if (isElectron()) {
                    window.electronAPI.send('runNuCAD');
                }
            } catch (err) {
                console.error(err);
                Modal.error({
                    title: t('BTN_RUN_NUCAD'),
                    content: err?.message || String(err),
                });
            }
        },
    });
};
