import { createSlice } from "@reduxjs/toolkit";
// LQFP    0 //,LQFP
// SOP     1
// BT      2 //BT_QFN
// BGA     3
const pkg_table = ["QFN", "SOP", "BT", "BGA"];

const r_pkg = createSlice({
    name: "r_pkg",
    initialState: "",
    reducers: {
        setPkg(state, action) {
            try {
                state = action.payload;
                // console.log(`pkg_frame = ${state.pkg_frame}, pins.length = ${state.pins.length}`)
                return pkg_table[state.pkg_frame] + state.pins.length;
            }
            catch (e) {
                console.error(e);
                return "UNSUPPORTED";
            }
        }
    }
});

export const { setPkg } = r_pkg.actions;
export default r_pkg.reducer;
